test('buffer param test cache', async () => {
  let count = 0
  const fn = Cache((set) => {
    count++
    return set.length + set.length
  })
  const s = new Buffer.from([1]);
  const s2 = new Buffer.from([1]);
  expect(await fn(s)).toBe(2);
  expect(await fn(s2)).toBe(2);
  expect(count).toBe(1);
});

